         },
         Err(_) => Ok((atoms::error(), "Couldn't convert MJML template").encode(env)),
     }
 }

+fn has_balanced_tags(input: &str) -> bool {
+    let mut offset = 0;
+    let mut tags = Vec::new();
+
+    while let Some(start) = input[offset..].find('<').map(|index| offset + index) {
+        if input[start..].starts_with("<!--") {
+            match input[start + 4..].find("-->") {
+                Some(end) => {
+                    offset = start + 4 + end + 3;
+                    continue;
+                }
+                None => return false,
+            }
+        }
+
+        if input[start..].starts_with("<![CDATA[") {
+            match input[start + 9..].find("]]>") {
+                Some(end) => {
+                    offset = start + 9 + end + 3;
+                    continue;
+                }
+                None => return false,
+            }
+        }
+
+        if input[start..].starts_with("<?") {
+            match input[start + 2..].find("?>") {
+                Some(end) => {
+                    offset = start + 2 + end + 2;
+                    continue;
+                }
+                None => return false,
+            }
+        }
+
+        let end = match find_tag_end(input, start + 1) {
+            Some(end) => end,
+            None => return false,
+        };
+
+        let tag = input[start + 1..end].trim();
+        offset = end + 1;
+
+        if tag.is_empty() || tag.starts_with('!') {
+            continue;
+        }
+
+        if let Some(closing_tag) = tag.strip_prefix('/') {
+            let name = tag_name(closing_tag);
+            if tags.pop().as_deref() != Some(name) {
+                return false;
+            }
+        } else {
+            let name = tag_name(tag);
+            if !tag.ends_with('/') && !is_void_tag(name) {
+                tags.push(name.to_string());
+            }
+        }
+    }
+
+    tags.is_empty()
+}
+
+fn find_tag_end(input: &str, mut offset: usize) -> Option<usize> {
+    let bytes = input.as_bytes();
+    let mut quote = None;
+
+    while offset < bytes.len() {
+        match bytes[offset] {
+            b'\'' | b'"' if quote == Some(bytes[offset]) => quote = None,
+            b'\'' | b'"' if quote.is_none() => quote = Some(bytes[offset]),
+            b'>' if quote.is_none() => return Some(offset),
+            _ => {}
+        }
+
+        offset += 1;
+    }
+
+    None
+}
